 - Format: application/json
 - Structure: Array[Object{name, date, venue: Object{name, address: Object{line1, line2, line3, city, state, postalCode, country}, seatingMap}, performers: Array[Object{name, genre}], tickets: Array[Object{type, price, currency}]}]
